SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admittime, a.dischtime, a.deathtime, s.stay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, em.emar_id, em.pharmacy_id, em.poe_id, em.poe_seq, em.order_provider_id, em.order_status, em.statusdescription, em.originalamount, em.originalrate, lag(em.order_status) OVER (PARTITION BY em.poe_id ORDER BY em.poe_seq) AS previous_order_status, lead(em.order_status) OVER (PARTITION BY em.poe_id ORDER BY em.poe_seq) AS next_order_status, dense_rank() OVER (PARTITION BY p.gender, p.anchor_year_group ORDER BY s.los DESC) AS tertile_rank, COUNT(DISTINCT s.stay_id) OVER (PARTITION BY p.gender, p.anchor_year_group) AS total_stays_in_tertile, COUNT(DISTINCT CASE WHEN a.deathtime IS NOT NULL THEN s.stay_id END) OVER (PARTITION BY p.gender, p.anchor_year_group) AS total_deaths_in_tertile, COUNT(DISTINCT CASE WHEN s.outtime - s.intime <= 30 THEN s.stay_id END) OVER (PARTITION BY p.gender, p.anchor_year_group) AS total_short_stays_in_tertile FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.subject_id = s.subject_id AND a.hadm_id = s.stay_id JOIN emar_detail em ON a.subject_id = em.subject_id AND a.hadm_id = em.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 85 AND 89 AND p.anchor_year BETWEEN 2019 AND 2020 AND p.anchor_year_group IN ('Hepatic failure') AND em.order_status = 'completed' AND previous_order_status != 'discontinued' AND next_order_status != 'discontinued';